let questionDraft=copy(state.questions),surveyDraftOpen=state.surveyOpen,mediaBusy=false;adminTab='events';
function admin(){if(adminTab==='events')return `<div class="layout single"><section>${eventsAdmin()}</section></div>`;return `<div class="layout"><section><button type="button" class="back-list" onclick="setAdmin('events')">← 返回 Event List</button>${adminContent()}</section><aside><div class="card side"><div class="eyebrow">EVENT WORKSPACE</div><h3>${esc(state.event.name)}</h3><span class="badge phase-${eventPhase()}">${PHASE_LABEL[eventPhase()]}</span> <span class="badge">${statusText()}</span><div class="details"><div><span>報名狀態</span>${registrationReason()||'報名開放中'}</div><div><span>問卷狀態</span>${state.surveyOpen?'開放填答':'暫停填答'} · ${state.questions.length} 題</div><div><span>成果前台</span>${state.publishedRecap?'已有發布版本':'尚未發布'}</div></div><p class="fine">Demo 資料與上傳素材保存在此瀏覽器，可跨前後台分頁預覽。不同裝置不會共用資料。</p></div><div class="note"><h4>從素材到完整成果頁</h4><p>上傳照片 → 選擇封面與版型 → 自動排版 → 預覽 → MKT Review → 發布</p></div></aside></div>`}
function adminContent(){if(adminTab==='events')return eventsAdmin();if(adminTab==='overview')return eventSettings();if(adminTab==='registrations')return registrationAdmin();if(adminTab==='survey')return surveyAdmin();if(adminTab==='editor')return recapEditor();if(adminTab==='review')return reviewPage();return brainPage()}
function eventSettings(){const e=state.event;return `<div class="statrow"><div class="stat"><span>已報名</span><strong>${state.registrations.length}<small> / ${e.capacity}</small></strong></div><div class="stat"><span>問卷回覆</span><strong>${state.responses.length}</strong></div><div class="stat"><span>成果素材</span><strong>${state.assets.length}</strong></div></div><form id="eventSettings" class="card content" onsubmit="saveEvent(event)" oninput="updateBannerPreview()"><div class="sectiontitle"><div><div class="eyebrow">EVENT & REGISTRATION</div><h3 style="margin-top:10px">活動與報名設定</h3></div><button class="primary" type="submit">儲存設定</button></div>${bannerSettings()}<h4 class="form-heading">活動基本資訊</h4>${field('活動名稱','eventName',e.name,'text','required maxlength="120"')}${field('活動標語','tagline',e.tagline,'text','maxlength="150"')}${field('活動標籤（以逗號分隔，前台顯示為 #標籤）','tags',e.tags||'','text','maxlength="120"')}<label for="intro">活動介紹</label><textarea id="intro" name="intro" maxlength="5000">${esc(e.intro)}</textarea><div class="form-grid">${field('活動日期','eventDate',e.date,'date','required')}${field('開始時間','start',e.start,'time','required')}${field('結束時間','end',e.end,'time','required')}${field('活動地點／線上會議資訊','venue',e.venue,'text','required maxlength="200"')}<div><label for="mode">活動形式</label><select id="mode" name="mode">${['實體','線上','實體＋線上'].map(v=>`<option ${e.mode===v?'selected':''}>${v}</option>`).join('')}</select></div>${field('參與對象','audience',e.audience,'text','maxlength="200"')}</div><label for="agenda">活動議程（每行：時間｜內容）</label><textarea id="agenda" name="agenda" maxlength="5000">${esc(e.agenda)}</textarea><h4 class="form-heading">報名規則</h4><div class="form-grid">${field('報名開始時間（台北時間，空白＝立即開放）','regStart',e.regStart||'','datetime-local')}<div><label for="statusOverride">前台活動狀態</label><select id="statusOverride" name="statusOverride">${[['auto','自動（依日期判斷）'],['open','強制：報名中'],['soon','強制：Coming soon'],['ended','強制：已結束']].map(([v,t])=>`<option value="${v}" ${(e.statusOverride||'auto')===v?'selected':''}>${t}</option>`).join('')}</select><p class="fine">目前判斷結果：${PHASE_LABEL[eventPhase()]}。自動規則：活動結束後為已結束；未到報名開始時間為 Coming soon；其餘為報名中。</p></div>${field('名額上限','capacity',e.capacity,'number','required min="1" max="100000"')}${field('報名截止時間（台北時間）','deadline',e.deadline,'datetime-local','required')}</div><label class="checkline"><input type="checkbox" name="registrationOpen" ${e.registrationOpen?'checked':''}> 開放線上報名</label><h4 class="form-heading">報名表欄位</h4>${registrationFieldSettings()}<div class="actions"><button type="button" onclick="previewRegistrationForm()">預覽報名表</button><button class="primary">儲存活動與報名設定</button><button type="button" onclick="window.open(SITE_BASE+'?e='+encodeURIComponent(state.id),'_blank','noopener')">查看此活動前台 ↗</button></div></form>`}
function saveEvent(e){e.preventDefault();const f=new FormData(e.target),capacity=Number(f.get('capacity'));if(f.get('end')<=f.get('start')){toast('結束時間需晚於開始時間');return}if(capacity<state.registrations.length){toast('名額上限不能小於目前報名人數');return}if(f.get('deadline')>`${f.get('eventDate')}T${f.get('end')}`){toast('報名截止時間不能晚於活動結束');return}if(f.get('regStart')&&f.get('regStart')>=f.get('deadline')){toast('報名開始時間需早於報名截止時間');return}if(bannerBusy){toast('Banner 正在儲存，請稍候');return}if(bannerDraft.bannerMode==='image'&&!mediaURL(bannerDraft.bannerId)){toast('請先上傳 Banner 或改用預設視覺');return}const registrationFields=readRegistrationSettings(f),industryOptions=[...new Set(String(f.get('industryOptions')||'').split('\n').map(v=>v.trim()).filter(Boolean))];if(registrationFields.industry.enabled&&industryOptions.length<2){toast('產業類別請至少設定兩個不同選項');return}const next={...bannerDraft,registrationFields,industryOptions,name:f.get('eventName').trim(),tagline:f.get('tagline').trim(),tags:String(f.get('tags')||'').trim(),intro:f.get('intro').trim(),date:f.get('eventDate'),start:f.get('start'),end:f.get('end'),venue:f.get('venue').trim(),mode:f.get('mode'),audience:f.get('audience').trim(),agenda:f.get('agenda'),capacity,deadline:f.get('deadline'),regStart:f.get('regStart')||'',statusOverride:f.get('statusOverride')||'auto',registrationOpen:f.has('registrationOpen'),department:registrationFields.department.enabled,company:registrationFields.company.enabled,phone:registrationFields.phone.enabled};if(!next.name||!next.venue){toast('請填寫活動名稱與地點');return}state.event=next;if(save()){render();toast('已儲存，前台活動頁與報名表已更新')}}
function registrationAdmin(){return `<div class="card content"><div class="sectiontitle"><h3>報名名單</h3><button onclick="exportRegistrations()" ${state.registrations.length?'':'disabled'}>匯出報名 CSV ↓</button></div><p class="fine">目前 ${state.registrations.length} / ${state.event.capacity} 人，僅包含此瀏覽器的示範報名。</p>${state.registrations.length?`<div class="table-scroll"><table><thead><tr><th>報名姓名 / Email</th><th>公司名稱 / 部門</th><th>聯絡電話</th><th>產業類別</th><th>職稱</th><th>報名時間</th></tr></thead><tbody>${state.registrations.map(r=>`<tr><td>${esc(r.name)}<small>${esc(r.email)}</small></td><td>${esc(r.company||'—')}<small>${esc(r.department||'')}</small></td><td>${esc(r.phone||'—')}</td><td>${esc(r.industry||'—')}</td><td>${esc(r.jobTitle||'—')}</td><td>${esc(r.date)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">尚無報名資料。可先儲存活動設定，再到前台試填報名表。</div>'}</div>`}
function exportRegistrations(){csvDownload([['報名姓名','公司名稱','Email','聯絡電話','產業類別','職稱','部門','報名時間'],...state.registrations.map(r=>[r.name,r.company,r.email,r.phone,r.industry,r.jobTitle,r.department,r.date])],'event-registrations.csv')}
function surveyAdmin(){return `<div class="card content"><div class="sectiontitle"><div><div class="eyebrow">SURVEY STUDIO</div><h3 style="margin-top:10px">讓每次回饋，都更有方向。</h3></div><span class="badge">${state.questions.length} 題 · v${state.surveyVersion}</span></div><div class="subnav"><button class="${surveyTab==='builder'?'primary':''}" onclick="surveyTab='builder';render()">問卷編輯</button><button class="${surveyTab==='responses'?'primary':''}" onclick="surveyTab='responses';render()">回覆與匯出（${state.responses.length}）</button><button class="${surveyTab==='qr'?'primary':''}" onclick="surveyTab='qr';render()">問卷 QR Code</button></div>${surveyTab==='responses'?surveyResponses():surveyTab==='qr'?surveyQR():surveyBuilder()}</div>`}
function surveyBuilder(){return `<p class="fine">從題庫加入問題，也可以自訂題目、選項與必填規則。儲存後會同步更新前台問卷。</p><div class="question-bank"><h4>常用題庫</h4><div class="bank-grid">${QUESTION_BANK.map((q,i)=>`<button type="button" onclick="addQuestion(${i})"><small>${{rating:'評分題',single:'單選題',multi:'複選題',text:'文字題'}[q.type]}</small>${esc(q.title)}<span>＋ 加入問卷</span></button>`).join('')}</div></div><div class="sectiontitle" style="margin-top:28px"><h3>編輯問卷 · ${questionDraft.length} 題</h3><button onclick="addCustomQuestion()">＋ 自訂題目</button></div><div class="question-list">${questionDraft.map((q,i)=>`<section class="question-editor"><div class="question-heading"><span class="badge">QUESTION ${String(i+1).padStart(2,'0')}</span><div><button type="button" aria-label="上移第 ${i+1} 題" onclick="moveQuestion(${i},-1)" ${i===0?'disabled':''}>↑</button><button type="button" aria-label="下移第 ${i+1} 題" onclick="moveQuestion(${i},1)" ${i===questionDraft.length-1?'disabled':''}>↓</button><button type="button" onclick="removeQuestion(${i})">移除</button></div></div><label for="questionTitle${i}">題目</label><input id="questionTitle${i}" value="${esc(q.title)}" maxlength="300" oninput="questionDraft[${i}].title=this.value"><div class="form-grid"><div><label for="questionType${i}">題型</label><select id="questionType${i}" onchange="changeQuestionType(${i},this.value)">${[['rating','1–5 分評分'],['single','單選'],['multi','複選'],['text','文字回答']].map(([v,t])=>`<option value="${v}" ${q.type===v?'selected':''}>${t}</option>`).join('')}</select></div><label class="checkline"><input type="checkbox" ${q.required?'checked':''} onchange="questionDraft[${i}].required=this.checked"> 必填</label></div>${['single','multi'].includes(q.type)?`<label for="questionOptions${i}">選項（每行一個）</label><textarea id="questionOptions${i}" oninput="questionDraft[${i}].options=this.value.split('\n')">${esc(q.options.join('\n'))}</textarea>`:''}</section>`).join('')||'<div class="empty">從上方題庫加入第一個問題。</div>'}</div><label class="checkline"><input id="surveyOpen" type="checkbox" ${surveyDraftOpen?'checked':''} onchange="surveyDraftOpen=this.checked"> 開放前台填答</label><div class="actions"><button class="primary" onclick="saveSurvey()">儲存問卷</button><button onclick="previewSurvey()">預覽問卷</button></div>`}
function addQuestion(index){if(questionDraft.length>=20){toast('Demo 最多 20 題');return}const q=copy(QUESTION_BANK[index]);q.id=crypto.randomUUID();questionDraft.push(q);render();toast('已加入問題，儲存後更新前台')}
function addCustomQuestion(){if(questionDraft.length>=20)return;questionDraft.push({id:crypto.randomUUID(),type:'text',title:'',required:false,options:[]});render()}
function removeQuestion(i){questionDraft.splice(i,1);render()}
function moveQuestion(i,d){if(!questionDraft[i+d])return;[questionDraft[i],questionDraft[i+d]]=[questionDraft[i+d],questionDraft[i]];render()}
function changeQuestionType(i,type){questionDraft[i].type=type;if(['single','multi'].includes(type)&&questionDraft[i].options.length<2)questionDraft[i].options=['選項一','選項二'];render()}
function validQuestions(){if(!questionDraft.length){toast('請至少加入一個問題');return false}for(const q of questionDraft){if(!q.title.trim()){toast('請填寫每個問題的題目');return false}if(['single','multi'].includes(q.type)){const options=[...new Set(q.options.map(s=>s.trim()).filter(Boolean))];if(options.length<2){toast('選擇題至少需要兩個不同選項');return false}q.options=options}}return true}
function saveSurvey(){if(!validQuestions())return;state.questions=copy(questionDraft);state.surveyOpen=surveyDraftOpen;state.surveyVersion++;if(save()){render();toast('問卷已儲存，前台題目已更新')}}
function previewSurvey(){if(!validQuestions())return;showDialog('問卷預覽',surveyForm(questionDraft,true))}
function defaultSurveyURL(){const u=new URL(SITE_BASE,location.href);u.search='';u.hash='';u.searchParams.set('e',state.id);u.searchParams.set('view','survey');return u.href}
function surveyURL(){return (state.surveyUrl||'').trim()||defaultSurveyURL()}
function validSurveyURL(v){try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)}catch{return false}}
function surveyQR(){const url=surveyURL();return `<p class="fine">掃描 QR Code 會開啟前台「現場問卷」分頁。問卷未開放時，前台顯示「問卷目前未開放填答」。</p>${state.surveyOpen?'':'<div class="empty" style="margin:12px 0">目前問卷為暫停填答，請先於「問卷編輯」勾選「開放前台填答」並儲存。</div>'}<div class="form-grid"><div style="grid-column:1/-1"><label for="surveyUrlInput">問卷網址</label><input id="surveyUrlInput" type="url" value="${esc(state.surveyUrl||'')}" placeholder="${esc(defaultSurveyURL())}" oninput="drawSurveyQR()"><p class="fine" id="surveyUrlHint"></p></div></div><div id="surveyQRBox" style="margin:18px 0;text-align:center"></div><div class="actions"><button class="primary" type="button" onclick="saveSurveyURL()">儲存網址</button><button type="button" onclick="downloadSurveyQR()">下載 PNG ↓</button><button type="button" onclick="copySurveyURL()">複製網址</button><button type="button" onclick="window.open(surveyURL(),'_blank','noopener')">開啟問卷頁 ↗</button><button type="button" onclick="resetSurveyURL()">還原預設網址</button></div>`}
function currentSurveyInput(){const el=$('surveyUrlInput');const v=(el?el.value:'').trim();return v||defaultSurveyURL()}
function drawSurveyQR(){const box=$('surveyQRBox'),hint=$('surveyUrlHint');if(!box)return;const url=currentSurveyInput();if(!validSurveyURL(url)){box.innerHTML='<div class="empty">請輸入 http:// 或 https:// 開頭的有效網址。</div>';hint.textContent='';return}let local=false;try{local=/^(localhost|127\.|0\.0\.0\.0|\[::1\])/.test(new URL(url).hostname)}catch{}hint.textContent=local?'此網址為本機位址，手機掃描後無法連線。請填入可從手機存取的正式或測試網址。':'目前編碼網址：'+url;try{const c=QR.toCanvas(url,{scale:8,label:''});c.style.cssText='width:min(100%,280px);height:auto;image-rendering:pixelated;border:1px solid var(--line);border-radius:8px';box.replaceChildren(c)}catch(err){box.innerHTML='<div class="empty">'+esc(err.message)+'</div>'}}
function saveSurveyURL(){const v=($('surveyUrlInput').value||'').trim();if(v&&!validSurveyURL(v)){toast('請輸入有效的 http(s) 網址');return}state.surveyUrl=v;if(save()){drawSurveyQR();toast(v?'問卷網址已儲存':'已使用預設問卷網址')}}
function resetSurveyURL(){state.surveyUrl='';if(save()){render();toast('已還原預設問卷網址')}}
function downloadSurveyQR(){const url=currentSurveyInput();if(!validSurveyURL(url)){toast('請輸入有效的 http(s) 網址');return}const c=QR.toCanvas(url,{scale:12,label:(state.event.name||'')+' 現場問卷'});c.toBlob(b=>{if(!b){toast('下載失敗');return}const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='event-survey-qr.png';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)},'image/png')}
async function copySurveyURL(){const url=currentSurveyInput();try{await navigator.clipboard.writeText(url);toast('已複製問卷網址')}catch{toast('無法自動複製，請手動複製輸入框內容')}}
function surveyResponses(){return `<div class="sectiontitle"><p class="fine">回覆保留填答當下的題目文字，修改問卷不會改動既有答案。</p><button onclick="exportCSV()" ${state.responses.length?'':'disabled'}>匯出問卷 CSV ↓</button></div>${state.responses.map((r,i)=>`<div class="response-card"><h4>回覆 ${i+1} <small class="fine">${esc(r.date)} · v${r.version||1}</small></h4>${r.answers?r.answers.map(a=>`<p><b>${esc(a.title)}</b><br>${esc(Array.isArray(a.value)?a.value.join('、'):a.value||'未填寫')}</p>`).join(''):`<p>舊版回覆：${esc(r.rating)} 分 / ${esc(r.takeaway)} / ${esc(r.feedback)}</p>`}</div>`).join('')||'<div class="empty">尚未收到回覆。</div>'}`}
function exportCSV(){const rows=[['回覆編號','時間','問卷版本','題目','答案']];state.responses.forEach((r,i)=>{const answers=r.answers||[{title:'整體滿意度',value:r.rating},{title:'最有收穫',value:r.takeaway},{title:'建議',value:r.feedback}];answers.forEach(a=>rows.push([i+1,r.date,r.version||1,a.title,Array.isArray(a.value)?a.value.join('；'):a.value]))});csvDownload(rows,'event-survey-responses.csv')}
function recapEditor(){return `<div class="card content"><div class="sectiontitle"><div><div class="eyebrow">RECAP PAGE BUILDER</div><h3 style="margin-top:10px">上傳照片，組成活動成果頁。</h3></div><span class="badge">${statusText()}</span></div><p class="fine">照片會自動排成封面與相片牆；影片與簡報會放入各自的內容區塊。可調整順序、照片說明與版型。${state.publishedRecap?'前台保留已發布版本，這裡的修改會另存草稿。':''}</p><form id="recapForm" onsubmit="saveDraft(event)">${field('成果頁標題','resultTitle',state.title,'text','required maxlength="150"')}<label for="resultSummary">活動回顧文字</label><textarea id="resultSummary" name="resultSummary" required maxlength="10000">${esc(state.summary)}</textarea><label for="theme">Landing page 版型</label><select id="theme" name="theme"><option value="editorial" ${state.theme==='editorial'?'selected':''}>Editorial · 大圖封面＋交錯相片牆</option><option value="gallery" ${state.theme==='gallery'?'selected':''}>Gallery · 大圖封面＋整齊相片網格</option></select>${recapFactsEditor()}<div class="file"><div class="eyebrow">YOUR MOMENTS, BEAUTIFULLY ARRANGED</div><h3 style="margin-top:12px">把活動精彩片段放進來。</h3><p class="fine">照片 JPG / PNG / WebP / GIF、影片、PDF / PPT 簡報<br>每個檔案最多 80 MB，素材儲存在此瀏覽器。</p><input aria-label="上傳成果照片影片簡報" type="file" multiple accept="image/jpeg,image/png,image/webp,image/gif,video/*,.pdf,.ppt,.pptx" onchange="addFiles(this.files)" ${mediaBusy?'disabled':''}></div><div id="mediaEditor">${mediaEditor()}</div><div class="actions"><button type="button" class="primary" onclick="generateLanding()" ${mediaBusy?'disabled':''}>產生 Landing page 預覽 ↗</button><button type="submit" ${mediaBusy?'disabled':''}>儲存草稿</button><button type="submit" name="action" value="review" ${mediaBusy?'disabled':''}>儲存並送 MKT Review →</button></div></form></div>`}
function recapFactsEditor(){const show=recapFactsShow(),e=state.event,val={time:`${dateLabel(e.date)} ${e.start||''}–${e.end||''}`,venue:`${e.venue||'—'}（${e.mode||''}）`,attendees:`${state.registrations.length} 人（目前報名數）`,responses:`${state.responses.length} 份（目前回覆數）`};return `<h4 class="form-heading">前台成果頁顯示資訊</h4><p class="fine">數值自動帶入活動設定、報名名單與問卷回覆；勾選的項目才會顯示在成果頁。人數與問卷數以送 MKT Review 當下的數字為準。</p><div class="inline-checks">${RECAP_FACTS.map(([k,l])=>`<label class="checkline"><input type="checkbox" name="fact_${k}" ${show[k]?'checked':''}> ${l}：<span class="fine">${esc(val[k])}</span></label>`).join('')}</div>`}
function mediaEditor(){return state.assets.length?`<div class="media-grid">${state.assets.map((a,i)=>`<div class="media-card">${a.type.startsWith('image/')&&mediaURL(a.id)?`<img src="${mediaURL(a.id)}" alt="${esc(a.caption||a.name)}">`:`<div class="media-placeholder">${a.type.startsWith('video/')?'VIDEO':'FILE'}<br><small>${esc(a.name)}</small></div>`}<div class="media-card-body"><div class="sectiontitle"><small class="fine">${esc(a.name)}</small><b>${String(i+1).padStart(2,'0')}</b></div>${a.type.startsWith('image/')?`<label class="checkline"><input type="radio" name="coverId" value="${a.id}" ${state.coverId===a.id||(!state.coverId&&state.assets.find(x=>x.type.startsWith('image/'))?.id===a.id)?'checked':''}> 作為封面</label>`:''}<label for="caption_${a.id}">照片／素材說明</label><input id="caption_${a.id}" name="caption_${a.id}" value="${esc(a.caption||'')}" maxlength="200" placeholder="例如：現場交流與小組討論"><div class="actions"><button type="button" aria-label="上移素材 ${i+1}" onclick="moveAsset(${i},-1)" ${i===0?'disabled':''}>↑</button><button type="button" aria-label="下移素材 ${i+1}" onclick="moveAsset(${i},1)" ${i===state.assets.length-1?'disabled':''}>↓</button><button type="button" onclick="removeAsset(${i})">移除</button></div>${!mediaURL(a.id)?'<p class="fine">檔案未載入，請重新選取原檔。</p>':''}</div></div>`).join('')}</div>`:'<div class="empty">加入至少一張照片，即可產生活動成果 Landing page。</div>'}
function readRecapForm(validate=true){const form=$('recapForm');if(!form)return true;if(validate&&!form.reportValidity())return false;const f=new FormData(form);state.title=String(f.get('resultTitle')).trim();state.summary=String(f.get('resultSummary')).trim();state.theme=f.get('theme');state.coverId=f.get('coverId')||'';state.recapFacts=Object.fromEntries(RECAP_FACTS.map(([k])=>[k,f.has('fact_'+k)]));for(const a of state.assets)a.caption=String(f.get('caption_'+a.id)||'').trim();return !validate||!!state.title&&!!state.summary}
function markDraft(){state.status='draft';state.reviewRecap=null}
async function addFiles(files){if(mediaBusy)return;readRecapForm(false);mediaBusy=true;toast('正在儲存素材…');let added=0,failed=0;for(const file of files){if(file.size>80*1024*1024||!(/^image\/(jpeg|png|webp|gif)$/.test(file.type)||file.type.startsWith('video/')||/\.(pdf|ppt|pptx)$/i.test(file.name))){failed++;continue}if(file.type.startsWith('image/')){try{const bitmap=await createImageBitmap(file);bitmap.close()}catch{failed++;continue}}let a=state.assets.find(x=>x.name===file.name&&x.size===file.size);if(a&&mediaURL(a.id))a=null;const fresh=!a;if(!a)a={id:crypto.randomUUID(),name:file.name,size:file.size,type:file.type||'application/octet-stream',caption:''};try{await storeMedia(a.id,file)}catch{failed++;continue}const old=uploads.find(x=>x.id===a.id);if(old)URL.revokeObjectURL(old.url);uploads=uploads.filter(x=>x.id!==a.id);uploads.push({...a,file,url:URL.createObjectURL(file)});if(fresh)state.assets.push(a);added++}if(added){markDraft();save()}mediaBusy=false;render();toast(`${added} 個素材已加入${failed?`，${failed} 個因格式、大小或儲存空間無法加入`:''}`)}
function moveAsset(i,d){readRecapForm(false);if(!state.assets[i+d])return;[state.assets[i],state.assets[i+d]]=[state.assets[i+d],state.assets[i]];markDraft();save();render()}
function removeAsset(i){readRecapForm(false);const [removed]=state.assets.splice(i,1);if(state.coverId===removed.id)state.coverId='';markDraft();save();render()}
function readyPhotos(){const photos=state.assets.filter(a=>a.type.startsWith('image/'));if(!photos.length){toast('請先加入至少一張照片');return false}if(photos.some(a=>!mediaURL(a.id))){toast('部分照片檔案未載入，請重新選取後再產生');return false}return true}
function generateLanding(){if(!readRecapForm()||!readyPhotos())return;markDraft();if(!save())return;render();showDialog('Landing page 草稿預覽',landingHTML(snapshotDraft(),{preview:true}),true)}
function saveDraft(e){e.preventDefault();if(!readRecapForm())return;const review=e.submitter?.value==='review';if(review&&!readyPhotos())return;markDraft();if(review){state.reviewRecap=snapshotDraft();state.status='review';adminTab='review'}if(save()){render();toast(review?'完整 Landing page 已送 MKT Review':'成果草稿已儲存')}}
function reviewPage(){const recap=state.reviewRecap||snapshotDraft();return `<div class="card content"><div class="sectiontitle"><div><div class="eyebrow">CONTENT REVIEW</div><h3 style="margin-top:10px">MKT 成果頁審核</h3></div><span class="badge">${statusText()}</span></div><p class="fine">審核的是完整 Landing page；文案、封面與照片順序都依送審版本呈現。</p><div class="actions" style="margin-bottom:20px"><button onclick="previewReview()">全螢幕預覽 Landing page ↗</button><button onclick="setAdmin('editor')">返回成果編輯</button></div><div class="landing-review-frame">${landingHTML(recap,{preview:true})}</div>${state.comment?`<div class="review"><b>MKT 意見</b><p>${esc(state.comment)}</p></div>`:''}<label for="reviewNote">審核意見</label><textarea id="reviewNote" placeholder="請填寫調整建議…" ${state.status==='review'?'':'disabled'}>${esc(state.comment)}</textarea><div class="actions"><button onclick="reviewAction('changes')" ${state.status==='review'?'':'disabled'}>退回修改</button><button class="primary" onclick="reviewAction('approved')" ${state.status==='review'?'':'disabled'}>核准成果頁</button><button class="primary" onclick="publish()" ${state.status==='approved'?'':'disabled'}>發布 Landing page ↗</button></div>${state.publishedRecap?'<div class="actions"><a class="download-link" href="${SITE_BASE}recap/" target="_blank" rel="noopener">查看已發布成果頁 ↗</a></div>':''}</div>`}
function previewReview(){showDialog('MKT Review · Landing page',landingHTML(state.reviewRecap||snapshotDraft(),{preview:true}),true)}
function reviewAction(status){if(state.status!=='review'||!state.reviewRecap)return;const note=$('reviewNote').value.trim();if(status==='changes'&&!note){toast('請填寫修改意見');return}state.comment=note;state.status=status;if(save()){render();toast(status==='approved'?'已核准，可發布成果頁':'已退回修改')}}
function publish(){if(state.status!=='approved'||!state.reviewRecap)return;state.publishedRecap=copy(state.reviewRecap);state.publishedRecap.publishedAt=timestamp();state.status='published';state.synced=false;if(save()){render();toast('Landing page 已發布到前台')}}
function brainPage(){return `<div class="card content"><div class="eyebrow">EXPERTHUB KNOWLEDGE</div><h3 style="margin-top:14px">成果發布後，累積團隊知識。</h3><p class="bodycopy">此處保留既有 AI 大腦串接的流程示範，不會呼叫 OpenAI 或正式知識庫。</p><div class="status">成果頁：${state.publishedRecap?'已有發布版本':'尚未發布'}<br>同步狀態：${state.synced?'已完成示範同步':'尚未同步'}</div><button class="primary" onclick="syncBrain()" ${!state.publishedRecap||state.synced?'disabled':''}>${state.synced?'已完成示範同步':'模擬同步已發布成果'}</button>${state.publishedRecap?'<div class="actions"><a class="download-link" href="${SITE_BASE}recap/" target="_blank" rel="noopener">查看知識來源：活動成果頁 ↗</a></div>':''}</div>`}
function syncBrain(){if(!state.publishedRecap)return;state.synced=true;if(save()){render();toast('僅完成流程示範，未寫入正式知識庫')}}
async function resetDemo(){if(mediaBusy||bannerBusy)return;if(!confirm('清除此瀏覽器的示範活動設定、問卷、報名與素材？'))return;localStorage.removeItem(KEY);try{const db=await getMediaDB();await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').clear();tx.oncomplete=resolve;tx.onerror=reject})}catch{}location.reload()}
function resetDrafts(){bannerDraft=Object.fromEntries(['bannerMode','bannerId','bannerName','bannerShowText','bannerAlt','cardImageId','cardImageName'].map(key=>[key,state.event[key]]));questionDraft=copy(state.questions);surveyDraftOpen=state.surveyOpen}
function switchEvent(id,tabName){if(mediaBusy||bannerBusy){toast('素材正在儲存，請稍候');render();return}if(!root.events.some(e=>e.id===id))return;pickEvent(id);root.currentId=id;resetDrafts();if(tabName)adminTab=tabName;if(save()){render()}}
function phaseBadge(ev){const ph=eventPhase(ev),manual=['open','soon','ended'].includes(ev.event.statusOverride);return `<span class="badge phase-${ph}">${PHASE_LABEL[ph]}</span>${manual?'<small class="fine"> 手動</small>':''}`}
function eventsAdmin(){return `<div class="card content"><div class="sectiontitle"><div><div class="eyebrow">EVENTS</div><h3 style="margin-top:10px">Event List</h3></div><button class="primary" onclick="addEvent()">＋ 新增活動</button></div><p class="fine">前台依活動狀態分為「報名中／Coming soon／已結束」。點選活動進入該活動的編輯頁；報名、問卷、成果與 Review 皆針對該活動。</p><div class="table-scroll"><table class="events-table"><thead><tr><th>活動</th><th>日期</th><th>前台狀態</th><th>報名</th><th>問卷</th><th>成果</th><th></th></tr></thead><tbody>${root.events.map(ev=>`<tr class="clickrow" tabindex="0" onclick="switchEvent('${ev.id}','overview')" onkeydown="if(event.key==='Enter')switchEvent('${ev.id}','overview')"><td><b>${esc(ev.event.name)}</b><small>${esc(ev.event.venue)}</small></td><td>${esc(dateLabel(ev.event.date))}<small>${esc(ev.event.start)}–${esc(ev.event.end)}</small></td><td>${phaseBadge(ev)}</td><td>${ev.registrations.length} / ${ev.event.capacity}</td><td>${ev.responses.length}</td><td>${{draft:'草稿',review:'待審核',changes:'待調整',approved:'審核通過',published:'已發布'}[ev.status]||'草稿'}</td><td><div class="actions"><button class="primary" onclick="event.stopPropagation();switchEvent('${ev.id}','overview')">編輯</button><button onclick="event.stopPropagation();duplicateEvent('${ev.id}')">複製</button><button onclick="event.stopPropagation();window.open(SITE_BASE+'?e='+encodeURIComponent('${ev.id}'),'_blank','noopener')">前台 ↗</button><button onclick="event.stopPropagation();deleteEvent('${ev.id}')" ${root.events.length<2?'disabled':''}>刪除</button></div></td></tr>`).join('')}</tbody></table></div></div>`}
function addEvent(){if(mediaBusy||bannerBusy)return;const day=n=>new Date(Date.now()+8*36e5+n*864e5).toISOString().slice(0,10);const ev=normalizeEventState(newEventState({id:newEventId(),event:{name:'新活動',tagline:'',tags:'',intro:'',date:day(30),deadline:day(29)+'T18:00',agenda:''},title:'新活動：活動精彩回顧'}));root.events.push(ev);if(save()){switchEvent(ev.id,'overview');toast('已新增活動，請完成活動與報名設定')}}
function duplicateEvent(id){const src=root.events.find(e=>e.id===id);if(!src)return;const ev=normalizeEventState(newEventState({id:newEventId(),event:{...copy(src.event),name:src.event.name+'（副本）',bannerMode:'default',bannerId:'',bannerName:'',bannerAlt:'',statusOverride:'auto'},questions:copy(src.questions),surveyOpen:src.surveyOpen,title:src.title,summary:src.summary,theme:src.theme}));root.events.push(ev);if(save()){render();toast('已複製活動設定與問卷題目（不含報名、回覆與素材）')}}
function deleteEvent(id){if(root.events.length<2)return;const ev=root.events.find(e=>e.id===id);if(!ev||!confirm(`刪除「${ev.event.name}」及其報名、問卷回覆與成果？此動作無法復原。`))return;root.events=root.events.filter(e=>e.id!==id);if(root.currentId===id)root.currentId=root.events[0].id;if(state.id===id){pickEvent(root.currentId);resetDrafts()}if(save()){render();toast('活動已刪除')}}
function setAdmin(section){if(mediaBusy||bannerBusy){toast('素材正在儲存，請稍候');return}adminTab=section;render()}
function render(){const listMode=adminTab==='events';document.querySelector('.crumb').textContent=listMode?'管理後台 / 活動管理 / Event List':'管理後台 / 活動管理 / '+state.event.name;document.querySelectorAll('.ev-only').forEach(el=>el.style.display=listMode?'none':'');const stepsEl=document.querySelector('.steps');if(stepsEl)stepsEl.style.display=listMode?'none':'';$('app').innerHTML=admin();$('eventSwitchBox').innerHTML=`<span class="fine">目前管理的活動</span><select aria-label="切換管理中的活動" onchange="switchEvent(this.value)">${root.events.map(ev=>`<option value="${esc(ev.id)}" ${ev.id===state.id?'selected':''}>${esc(ev.event.name)}</option>`).join('')}</select>`;document.querySelectorAll('[data-section]').forEach(b=>b.classList.toggle('on',b.dataset.section===adminTab));document.querySelectorAll('.step').forEach((s,i)=>s.classList.toggle('active',['events','overview','registrations'].includes(adminTab)?i===0:adminTab==='survey'?i===1:['editor','review'].includes(adminTab)?i===2:i===3));if(adminTab==='survey'&&surveyTab==='qr')drawSurveyQR()}
render();hydrateMedia().then(()=>render());
